    fare_cents = normalized['fare_cents']

    if mode == 'walk':
        base = 0
        rate = 0
    elif mode == 'bus':
        base = 140
        rate = 12
    elif mode == 'rail':
        base = 320
        rate = 25
    else:
        return None

    raw = fare_cents + base + rate * minutes
    if minutes >= 60:
        raw = raw * 0.9

    # Round to nearest cent, with half-up rounding
    quote_cents = int(raw + 0.5)

    return {
        'mode': mode,
        'origin': origin,
        'dest': dest,
        'minutes': minutes,
        'quote_cents': quote_cents
    }


def combine_segments(segments):
    return None


